create or replace function public.opponent_scout(p_competition text,p_team text) returns jsonb language sql stable security invoker set search_path=public as $$ with games as(select g.id,g.game_date,g.home_team,g.away_team,g.payload,row_number()over(order by g.game_date desc nulls last,g.id desc)rn,case when g.home_team=p_team then g.payload->'ui'->'calculated'->'home' else g.payload->'ui'->'calculated'->'away' end calc,case when g.home_team=p_team then g.payload->'raw'->'home' else g.payload->'raw'->'away' end raw,case when g.home_team=p_team then g.away_team else g.home_team end opponent from public.games g where g.competition=p_competition and(g.home_team=p_team or g.away_team=p_team)),a as(select count(*)games,avg((calc->>'pace')::numeric)pace,avg((calc->>'efg')::numeric)efg,avg((calc->>'tov')::numeric)tov_pct,avg((calc->>'orb')::numeric)orb_pct,avg((calc->>'ftr')::numeric)ftr,avg((raw->>'three_pa')::numeric)three_pa,avg((raw->>'oreb')::numeric)oreb,avg((raw->>'tov')::numeric)turnovers,avg((calc->>'pace')::numeric)filter(where rn<=5)l5_pace,avg((calc->>'efg')::numeric)filter(where rn<=5)l5_efg,avg((calc->>'tov')::numeric)filter(where rn<=5)l5_tov_pct,avg((calc->>'orb')::numeric)filter(where rn<=5)l5_orb_pct from games),tendencies as(select jsonb_build_array(jsonb_build_object('area','PACE','season',round(pace,1),'last5',round(l5_pace,1),'delta',round(l5_pace-pace,1),'sample_games',least(games,5)),jsonb_build_object('area','SHOOTING','season',round(efg,1),'last5',round(l5_efg,1),'delta',round(l5_efg-efg,1),'sample_games',least(games,5)),jsonb_build_object('area','TURNOVERS','season',round(tov_pct,1),'last5',round(l5_tov_pct,1),'delta',round(l5_tov_pct-tov_pct,1),'sample_games',least(games,5)),jsonb_build_object('area','REBOUNDING','season',round(orb_pct,1),'last5',round(l5_orb_pct,1),'delta',round(l5_orb_pct-orb_pct,1),'sample_games',least(games,5)))arr from a),roster as(select distinct player_id,player_name from public.game_player_stats where competition=p_competition and team_name=p_team and verified=true),signals as(select r.player_id,r.player_name,public.player_memory_v2(r.player_id,p_competition)memory from roster r),quality as(select count(*)checks,count(*)filter(where d.status='PASS')passed,count(*)filter(where d.status='FAIL')failed from public.data_quality_checks d where d.game_id in(select id from games where rn<=5))select jsonb_build_object('competition',p_competition,'team',p_team,'games',(select count(*)from games),'profile',(select jsonb_build_object('pace',round(pace,1),'efg',round(efg,1),'tov_pct',round(tov_pct,1),'orb_pct',round(orb_pct,1),'ftr',round(ftr,1),'three_pa',round(three_pa,1),'oreb',round(oreb,1),'turnovers',round(turnovers,1))from a),'tendencies',(select arr from tendencies),'player_signals',(select coalesce(jsonb_agg(jsonb_build_object('player_id',player_id,'player_name',player_name,'flag',memory->>'flag','confidence',memory->'confidence','summary',memory->'summary','last5',memory->'last5'))filter(where memory->>'flag'in('TREND','ROLE_CHANGE')),'[]'::jsonb)from signals),'evidence_games',(select coalesce(jsonb_agg(jsonb_build_object('game_id',id,'date',game_date,'opponent',opponent)order by game_date desc nulls last,id desc),'[]'::jsonb)from games where rn<=5),'verified_claims',(select coalesce(jsonb_agg(jsonb_build_object('claim',claim_text,'confidence',confidence,'sample_games',sample_games,'sample_minutes',sample_minutes,'games',evidence_game_ids,'video',video_evidence)order by confidence desc nulls last),'[]'::jsonb)from public.intelligence_claims where competition=p_competition and subject_name=p_team and status='VERIFIED'),'quality',(select jsonb_build_object('checks',checks,'passed',passed,'failed',failed,'status',case when failed>0 then 'REVIEW' when checks=0 then 'INSUFFICIENT_DATA' else 'VERIFIED' end)from quality));$$;revoke all on function public.opponent_scout(text,text) from public,anon;grant execute on function public.opponent_scout(text,text) to authenticated;